"""
One results figure for R3 and R4: each model's 10-fold cross-validation
accuracy (mean, with one sample standard deviation across folds) beside its
accuracy on the 25,000 test reviews from the joint test-set run.

Inputs:
    results/scores/<model>.csv        (10-fold scores, one row per fold)
    results/scores/test/<model>.csv   (test-set scores, one row)

Output:
    documentation/week10/figures/results_r3_r4.png

Usage: python scripts/results_figure.py
"""

# GenAI: this script was generated by Claude Code (Anthropic, Claude Opus 5.5)
# on 26 November 2026. The prompt, in full (originally in Chinese):
#   Claude had suggested: "R3/R4：一张图也没有。最省事的做法是用一张图覆盖两部分：
#   8 个模型的交叉验证准确率和测试集准确率并排的柱状图，数据现成。代码我来写，
#   并在注释里附上完整 prompt。"
#   ("R3/R4 have no figure at all. The simplest option is one figure covering
#   both: the 8 models' cross-validation accuracy and test-set accuracy side
#   by side as a bar chart; the data already exists. I will write the code and
#   put the full prompt in the comments.")
#   Prompt: "画一张合并图，配上不同形状的标记分清两组，每块内部按测试准确率从高到低排" ("Draw the combined figure. Using markers of different shapes to distinguish between the categories; within each section, items should be ordered by test accuracy, from highest to lowest.")

from pathlib import Path

import matplotlib.pyplot as plt
import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
SCORE_DIR = ROOT / "results" / "scores"
FIG_OUT = ROOT / "documentation" / "week10" / "figures" / "results_r3_r4.png"

# (panel title, [(label, score file name), ...]); labels match the README tables
PANELS = [
    ("R3: classical models", [
        ("Logistic regression", "lr_tfidf"),
        ("Random forest, 1–3 word n-grams", "rf_tfidf_ngram3"),
        ("Random forest", "rf_tfidf"),
        ("Naive Bayes", "mnb_tfidf"),
        ("Decision tree", "dt_tfidf"),
    ]),
    ("R4: neural networks", [
        ("MLP, TF-IDF + word pairs", "mlp_tfidf_bigram"),
        ("MLP, TF-IDF", "mlp_tfidf"),
        ("1D-CNN", "cnn"),
    ]),
]

CV_COLOR = "#6da7ec"     # light blue: cross-validation
TEST_COLOR = "#184f95"   # dark blue: test set
TEXT = "#0b0b0b"
TEXT_MUTED = "#52514e"
GRID = "#e4e3df"
OFFSET = 0.17            # vertical gap between the two marks of one model


def load(name):
    cv = pd.read_csv(SCORE_DIR / f"{name}.csv")["accuracy"]
    test = pd.read_csv(SCORE_DIR / "test" / f"{name}.csv")["accuracy"].iloc[0]
    assert len(cv) == 10, f"{name}: expected 10 folds, found {len(cv)}"
    return cv.mean(), cv.std(), test   # pandas std uses n - 1


def main():
    heights = [len(models) for _, models in PANELS]
    fig, axes = plt.subplots(
        len(PANELS), 1, sharex=True, figsize=(8, 5.6), dpi=200,
        gridspec_kw={"height_ratios": heights, "hspace": 0.35},
    )

    print(f"{'model':<34}{'CV mean':>9}{'CV SD':>8}{'test':>8}")
    for ax, (title, models) in zip(axes, PANELS):
        rows = [(label, *load(name)) for label, name in models]
        rows.sort(key=lambda r: r[3], reverse=True)   # best test accuracy on top

        for i, (label, cv_mean, cv_sd, test) in enumerate(rows):
            y = len(rows) - 1 - i
            print(f"{label:<34}{cv_mean:>9.4f}{cv_sd:>8.4f}{test:>8.4f}")
            ax.errorbar(
                cv_mean, y + OFFSET, xerr=cv_sd, fmt="o", ms=7, mew=2,
                mfc="white", mec=CV_COLOR, ecolor=CV_COLOR, elinewidth=2,
                capsize=0, zorder=3,
                label="10-fold CV mean ± 1 SD" if i == 0 else None,
            )
            ax.plot(
                test, y - OFFSET, "D", ms=6.5, color=TEST_COLOR, zorder=3,
                label="Test set, 25,000 reviews" if i == 0 else None,
            )
            # Test accuracy printed in a column to the right of the plot
            ax.text(1.01, y - OFFSET, f"{test:.4f}", transform=ax.get_yaxis_transform(),
                    va="center", fontsize=8.5, color=TEXT)

        ax.set_yticks(range(len(rows)))
        ax.set_yticklabels([r[0] for r in reversed(rows)], fontsize=9, color=TEXT)
        ax.set_ylim(-0.6, len(rows) - 0.4)
        ax.set_title(title, loc="left", fontsize=10, color=TEXT, fontweight="bold")
        ax.grid(axis="x", color=GRID, linewidth=0.8)
        ax.set_axisbelow(True)
        ax.tick_params(axis="y", length=0)
        ax.tick_params(axis="x", colors=TEXT_MUTED, labelsize=8.5)
        for side in ("top", "right", "left"):
            ax.spines[side].set_visible(False)
        ax.spines["bottom"].set_color(GRID)

    axes[0].text(1.01, 1.0, "Test", transform=axes[0].transAxes, va="bottom",
                 fontsize=8.5, color=TEXT_MUTED)
    axes[-1].set_xlim(0.70, 0.92)
    axes[-1].set_xlabel("Accuracy", fontsize=9, color=TEXT_MUTED)

    for ax in axes[:-1]:
        ax.tick_params(axis="x", length=0)

    # Legend in the same order as the marks in each row: CV above, test below
    handles, labels = axes[0].get_legend_handles_labels()
    order = sorted(range(len(labels)), key=lambda k: not labels[k].startswith("10-fold"))
    handles, labels = [handles[k] for k in order], [labels[k] for k in order]
    fig.legend(handles, labels, loc="upper center", ncol=2, frameon=False,
               fontsize=8.5, bbox_to_anchor=(0.55, 1.0))

    FIG_OUT.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(FIG_OUT, bbox_inches="tight", facecolor="white")
    plt.close(fig)
    print(f"\nSaved figure to {FIG_OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
